#include <algorithm>
#include <array>
#include <iostream>
#include <ranges>

using namespace std;

int main() {
    array<array<bool, 8>, 8> board;
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            char c;
            cin >> c;
            board[i][j] = c == '#';
        }
    }

    // 置くことができるマスを求める
    array<array<bool, 8>, 8> safe{};
    // はじめすべて true で初期化
    ranges::fill(safe | views::join, true);

    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            // コマが置かれていたら、
            if (board[i][j] == 1) {
                // 同じ行のマスに置くことはできない
                for (int k = 0; k < 8; k++) {
                    safe[i][k] = false;
                }
                // 同じ列のマスに置くことはできない
                for (int k = 0; k < 8; k++) {
                    safe[k][j] = false;
                }
            }
        }
    }

    // 置くことができるマスの合計を出力
    cout << ranges::count(safe | views::join, true) << endl;
    return 0;
}

#include <algorithm>
#include <array>
#include <iostream>

using namespace std;

int main() {
    // 各行・各列にコマがあるか
    // はじめはすべて false にしておく
    array<bool, 8> row{}, column{};

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            char c;
            cin >> c;
            // コマが置かれていたら
            if (c == '#') {
                // 対応する行と列を true に
                row[i] = true;
                column[j] = true;
            }
        }
    }

    // false の行数 × false の列数 が答え
    cout << ranges::count(row, false) * ranges::count(column, false) << endl;

    return 0;
}
